'use strict';
// Makes supabase/oto-feedback.bundle.ts: the oto-feedback Edge Function as ONE file (check.mjs + handler.mjs +
// index.ts), to paste into Supabase's dashboard editor. `node scripts/feedback-bundle.js --check` fails if it's out
// of date (test/feedback.test.js runs that).
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'supabase', 'functions', 'oto-feedback');
const out = path.join(__dirname, '..', 'supabase', 'oto-feedback.bundle.ts');
const read = (f) => fs.readFileSync(path.join(dir, f), 'utf8');
const strip = (s) => s.replace(/^import \{[^}]*\} from '\.\/[\w.]+';\n/gm, '').replace(/^export (const|function|async function) /gm, '$1 ');
const text = [
  '// GENERATED by scripts/feedback-bundle.js from supabase/functions/oto-feedback/: edit those files, not this one.',
  '// @ts-nocheck (the plain-JavaScript parts are checked by test/feedback.test.js)',
  '// Paste this whole file into Supabase → Edge Functions → oto-feedback (see docs/FEEDBACK_SETUP.md).',
  '',
  strip(read('index.ts')).replace(/^(import [^\n]+\n)+/m, (m) => `${m}\n// ---- check.mjs ----\n${strip(read('check.mjs'))}\n// ---- handler.mjs ----\n${strip(read('handler.mjs'))}\n// ---- index.ts ----\n`),
].join('\n');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== text) { console.error('supabase/oto-feedback.bundle.ts is out of date: run node scripts/feedback-bundle.js'); process.exit(1); }
  console.log('oto-feedback bundle is up to date');
} else { fs.writeFileSync(out, text); console.log(`wrote ${path.relative(process.cwd(), out)}`); }
